plssemBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "plssemBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "PLSsemLab",
                name = "plssem",
                version = c(0,0,0),
                options = options,
                results = plssemResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' PLS-SEM
#'
#' Partial least squares structural equation modeling: reflective and 
#' formative constructs built from boxes, model validation before estimation, 
#' loadings and weights, reliability, convergent and discriminant validity, 
#' collinearity of formative indicators, paths and explained variance, with 
#' plain-language interpretation.
#' 
#' @param data .
#' @param reflective .
#' @param formative .
#' @param reflectiveHoc .
#' @param formativeHoc .
#' @param hocApproach .
#' @param structural .
#' @param estimator .
#' @param innerScheme .
#' @param indicatorScale .
#' @param missing .
#' @param fornellLarcker .
#' @param bootstrap .
#' @param bootReps .
#' @param bootSeed .
#' @param ciLevel .
#' @param pathDiagram .
#' @param loadingsPlot .
#' @param htmtPlot .
#' @param moderationPlot .
#' @param diagramLayout .
#' @param diagramTitle .
#' @param diagramIndicators .
#' @param diagramCaption .
#' @param latentSize .
#' @param manifestSize .
#' @param nodeLabelSize .
#' @param latentFill .
#' @param manifestFill .
#' @param edgeWidth .
#' @param edgeColor .
#' @param nonsigDashed .
#' @param edgeLabels .
#' @param edgeLabelSize .
#' @param edgeDigits .
#' @param omegaCfa .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$model} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$measurementGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$measurement} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reliabilityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$htmtGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$htmt} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fornell} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$vifGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$vif} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$paths} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$r2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hocGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hocMeasurement} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hocReliability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$structuralGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$f2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$vifStruct} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$moderationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$simpleSlopes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$moderationPlots} \tab \tab \tab \tab \tab an array of images \cr
#'   \code{results$pathDiagram} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$loadingsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$htmtPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibilityCode} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$model$asDF}
#'
#' \code{as.data.frame(results$model)}
#'
#' @export
plssem <- function(
    data,
    reflective = list(
                list(label="Construct 1", vars=list())),
    formative = list(),
    reflectiveHoc = list(
                    list(label="Higher-order 1", components=list())),
    formativeHoc = list(
                    list(label="Higher-order 2", components=list())),
    hocApproach = "disjoint",
    structural = list(),
    estimator = "pls",
    innerScheme = "path",
    indicatorScale = "continuous",
    missing = "listwise",
    fornellLarcker = FALSE,
    bootstrap = FALSE,
    bootReps = 2000,
    bootSeed = 2026,
    ciLevel = 0.95,
    pathDiagram = TRUE,
    loadingsPlot = FALSE,
    htmtPlot = FALSE,
    moderationPlot = TRUE,
    diagramLayout = "treeLR",
    diagramTitle = "",
    diagramIndicators = TRUE,
    diagramCaption = TRUE,
    latentSize = 11,
    manifestSize = 6,
    nodeLabelSize = 1,
    latentFill = "theme",
    manifestFill = "theme",
    edgeWidth = "estimate",
    edgeColor = "theme",
    nonsigDashed = TRUE,
    edgeLabels = TRUE,
    edgeLabelSize = 0.8,
    edgeDigits = 2,
    omegaCfa = FALSE,
    showKeySummary = TRUE,
    showChoicesGuide = TRUE,
    showGuides = FALSE,
    showRepro = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("plssem requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- plssemOptions$new(
        reflective = reflective,
        formative = formative,
        reflectiveHoc = reflectiveHoc,
        formativeHoc = formativeHoc,
        hocApproach = hocApproach,
        structural = structural,
        estimator = estimator,
        innerScheme = innerScheme,
        indicatorScale = indicatorScale,
        missing = missing,
        fornellLarcker = fornellLarcker,
        bootstrap = bootstrap,
        bootReps = bootReps,
        bootSeed = bootSeed,
        ciLevel = ciLevel,
        pathDiagram = pathDiagram,
        loadingsPlot = loadingsPlot,
        htmtPlot = htmtPlot,
        moderationPlot = moderationPlot,
        diagramLayout = diagramLayout,
        diagramTitle = diagramTitle,
        diagramIndicators = diagramIndicators,
        diagramCaption = diagramCaption,
        latentSize = latentSize,
        manifestSize = manifestSize,
        nodeLabelSize = nodeLabelSize,
        latentFill = latentFill,
        manifestFill = manifestFill,
        edgeWidth = edgeWidth,
        edgeColor = edgeColor,
        nonsigDashed = nonsigDashed,
        edgeLabels = edgeLabels,
        edgeLabelSize = edgeLabelSize,
        edgeDigits = edgeDigits,
        omegaCfa = omegaCfa,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro)

    analysis <- plssemClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

